MASK64 = (1 << 64) - 1


def rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def slot(identifier, mask, capacity):
    mixed = (identifier ^ (mask * 0x9E3779B97F4A7C15)) & MASK64
    mixed ^= mixed >> 33
    mixed = (mixed * 0xFF51AFD7ED558CCD) & MASK64
    mixed ^= mixed >> 33
    mixed = (mixed * 0xC4CEB9FE1A85EC53) & MASK64
    mixed ^= mixed >> 33
    return mixed & (capacity - 1)


